package com.vandorlabs.neoforge.gear.client;

import com.vandorlabs.neoforge.gear.*;
import com.vandorlabs.neoforge.NativeGearItemModels;
import com.vandorlabs.animation.VisualClock;
import com.mojang.math.Axis;
import java.util.*;
import net.minecraft.client.*;
import net.minecraft.client.gui.screens.*;
import net.minecraft.core.*;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.nbt.*;
import net.minecraft.world.item.*;
import net.neoforged.api.distmarker.Dist;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.client.event.*;

/** Actual authored meshes, every size/mount/pose, item padding, immutable reload and pause-aware smoothing. */
@EventBusSubscriber(modid="vandorlabs",value=Dist.CLIENT)
public final class NativeGearRenderChecks {
    private record Scene(NativeGearEntity tile,double phase,double[] bounds){}
    private static List<Scene> scenes;private static int frames,generation,checks;private static boolean capture,done;private static java.util.concurrent.CompletableFuture<Void> reload;
    private static boolean enabled(){return Boolean.getBoolean("vandorlabs.gearRenderCheck");}
    private static final class Gallery extends Screen {Gallery(){super(net.minecraft.network.chat.Component.literal("Native arm authored poses"));}@Override public void render(net.minecraft.client.gui.GuiGraphics g,int x,int y,float partial){}}
    private static void need(boolean ok,String why){checks++;if(!ok)throw new AssertionError("Native gear render generation="+generation+": "+why);}
    private static void clock(){for(double interval:new double[]{1,3,4,12}){var sample=new NativeGearVisualClock.Sample();double previous=1;for(int frame=0;frame<=25*interval*8;frame++){double now=frame/8D,authority=Math.max(0,1-Math.floor(now/interval)/24D),actual=NativeGearVisualClock.advance(sample,authority,now);need(actual<=previous+1e-9&&actual>=authority-1e-9,"lagging animation remains within received support");previous=actual;}need(previous==0,"settled received endpoint");double now=25*interval;need(NativeGearVisualClock.advance(sample,0,now)==0,"repeated update stays settled");need(NativeGearVisualClock.advance(sample,.25,now+1)==0,"reversal correction keeps continuity");need(Math.abs(NativeGearVisualClock.advance(sample,.25,now+20)-.25)<1e-9,"blocked correction settles");}var clock=new VisualClock();clock.sample(1_000_000_000L,false);double before=clock.sample(2_000_000_000L,false);need(clock.sample(5_000_000_000L,true)==before&&clock.sample(8_000_000_000L,true)==before,"pause clock freezes");need(clock.sample(9_000_000_000L,false)==before,"resume excludes paused gap");}
    private static void prepare(){clock();var result=new ArrayList<Scene>();var registries=RegistryAccess.fromRegistryOfRegistries(BuiltInRegistries.REGISTRY);var mesh=NativeGearResources.bake();need(mesh!=null,"successful authored atlas publication");NativeGearDoubleRenderChecks.run(registries,mesh);for(var definition:NativeGearDefinition.values()){var stack=new ItemStack(NativeGearBindings.ITEMS.get(definition.id));var model=Minecraft.getInstance().getItemRenderer().getModel(stack,null,null,0);need(NativeGearItemModels.fits(model),"rotated GUI padding "+definition.id);need(model.getQuads(null,null,net.minecraft.util.RandomSource.create(0)).size()>0,"real authored item "+definition.id);need(!stack.getHoverName().getString().contains("block.vandorlabs"),"canonical translation "+definition.id);}
        for(Direction mount:Direction.values())for(var definition:new NativeGearDefinition[]{NativeGearDefinition.EXTENDER,NativeGearDefinition.LARGE_EXTENDER,NativeGearDefinition.ROTATING,NativeGearDefinition.LARGE_ROTATING})for(int mode=0;mode<(definition.kind==NativeGearDefinition.Kind.ROTATING?2:1);mode++)for(double phase:new double[]{1,.5,0}){var tile=NativeGearBindings.ENTITY.create(BlockPos.ZERO,NativeGearBindings.BLOCKS.get(definition.id).defaultBlockState().setValue(NativeGearBlock.ASSEMBLED,true));var tag=new CompoundTag();NativeGearSettings.defaults().writeSaved(tag);tag.putBoolean("ArmRotatePayload",mode==1);tag.putString("ArmMountDirection",mount.name());tag.putBoolean("GearController",true);tag.putInt("GearHeight",2);tag.putString("GearKind","NONE");tag.putDouble("GearProgress",phase);tag.putDouble("NativeGearLastEndpoint",1);var feet=new ListTag();feet.add(new IntArrayTag(new int[]{0,-2,0}));tag.put("GearFeet",feet);tile.loadWithComponents(tag,registries);need(!tile.inert()&&tile.assembly()!=null,"strict render snapshot "+definition+"/"+mount);double[] bounds={Double.POSITIVE_INFINITY,Double.POSITIVE_INFINITY,Double.POSITIVE_INFINITY,Double.NEGATIVE_INFINITY,Double.NEGATIVE_INFINITY,Double.NEGATIVE_INFINITY};NativeGearRenderer.emit(tile,phase,(name,transform,cache)->mesh.bounds(name,transform,bounds));need(Double.isFinite(bounds[0])&&bounds[3]>bounds[0],"authored positive geometry");result.add(new Scene(tile,phase,bounds));}
        need(result.size()==108,"six faces, regular/Large, three poses, both rotating modes");scenes=List.copyOf(result);System.out.println("[vandorlabs][gear-render] prepared generation="+generation+" scenes="+scenes.size()+" retained="+mesh.retainedBytes());}
    @SubscribeEvent public static void draw(ScreenEvent.Render.Post event){if(!enabled()||done)return;var mc=Minecraft.getInstance();if(mc.getOverlay()!=null)return;if(mc.screen instanceof AccessibilityOnboardingScreen intro){intro.onClose();return;}if(mc.screen instanceof TitleScreen){mc.getWindow().setWindowed(1280,720);mc.options.guiScale().set(2);mc.resizeDisplay();mc.setScreen(new Gallery());return;}if(!(event.getScreen() instanceof Gallery))return;if(reload!=null){if(!reload.isDone())return;reload.join();reload=null;}if(scenes==null)prepare();var gui=event.getGuiGraphics();gui.fill(0,0,640,360,0xFF202830);gui.flush();com.mojang.blaze3d.systems.RenderSystem.clear(org.lwjgl.opengl.GL11.GL_DEPTH_BUFFER_BIT,Minecraft.ON_OSX);if(frames>=4){var buffers=mc.renderBuffers().bufferSource();var consumer=buffers.getBuffer(net.minecraft.client.renderer.RenderType.cutout());var mesh=NativeGearResources.bake();for(int i=0;i<scenes.size();i++){var scene=scenes.get(i);var pose=gui.pose();pose.pushPose();try{var b=scene.bounds;double span=Math.max(b[3]-b[0],Math.max(b[4]-b[1],b[5]-b[2])),scale=17/Math.max(1,span);pose.translate(20+i%18*34,28+i/18*50,250);pose.scale((float)scale,(float)-scale,(float)scale);pose.mulPose(Axis.XP.rotationDegrees(20));pose.mulPose(Axis.YP.rotationDegrees(-30));pose.translate(-(b[0]+b[3])/2,-(b[1]+b[4])/2,-(b[2]+b[5])/2);NativeGearRenderer.emit(scene.tile,scene.phase,(name,transform,cache)->mesh.draw(name,transform,cache,pose.last(),consumer,0xF000F0,net.minecraft.client.renderer.texture.OverlayTexture.NO_OVERLAY));}finally{pose.popPose();}}buffers.endBatch();}gui.flush();frames++;capture=frames==4||frames==9;}
    @SubscribeEvent public static void shot(RenderFrameEvent.Post event)throws Exception{if(!enabled()||!capture||done)return;capture=false;var mc=Minecraft.getInstance();try(var image=Screenshot.takeScreenshot(mc.getMainRenderTarget())){var file=mc.gameDirectory.toPath().resolve("screenshots/native-gear-"+generation+"-"+(frames==4?"disabled":"positive")+".png");java.nio.file.Files.createDirectories(file.getParent());image.writeToFile(file);int scale=(int)mc.getWindow().getGuiScale();for(int i=0;i<108;i++){int ink=0;for(int y=0;y<48*scale;y++)for(int x=0;x<32*scale;x++){if((image.getPixelRGBA((4+i%18*34)*scale+x,(4+i/18*50)*scale+y)&0xFFFFFF)!=0x302820){ink++;need(x>0&&y>0&&x<32*scale-1&&y<48*scale-1,"uncropped authored scene="+i);}}need(frames==4?ink==0:ink>8,"negative/visible scene="+i+" ink="+ink);}}
        if(frames==9){need(NativeGearResources.bake().retainedBytes()<12*1024*1024,"weighted atlas cache bound");if(generation++==0){scenes=null;frames=0;reload=mc.reloadResourcePacks();}else{done=true;System.out.println("[vandorlabs][gear-render] title PASS checks="+checks+" sixFaces/regularLarge/extender/rotatingBothModes/threePoses/108Scenes/10PaddedItems/clockLagPauseRepeatReversal/reload/disabled");mc.stop();}}
    }
}
